namespace g2m {
namespace {
using json = nlohmann::json;
using strict::Reader;
// const unsigned char kSignalTiming[]: the bytes of data/signals/signal_timing.json, generated by CMake.
#include "signal_timing.inc"

constexpr double kBehindLineM = 0.5;   // an agent this far past the line still counts as at it (a stopped nose over the line)
constexpr double kCellM = 64.0;

std::int64_t mm_of(double metres) { return static_cast<std::int64_t>(std::llround(metres * 1000.0)); }
} // namespace

const char* to_string(SignalAspect aspect) {
    switch (aspect) {
        case SignalAspect::Red: return "red";
        case SignalAspect::RedAmber: return "red-amber";
        case SignalAspect::Green: return "green";
        case SignalAspect::Amber: return "amber";
    }
    return "?";
}

Result<SignalTiming> load_signal_timing(std::span<const std::byte> bytes) {
    const char* begin = reinterpret_cast<const char*>(bytes.data());
    const json j = json::parse(begin, begin + bytes.size(), nullptr, /*allow_exceptions=*/false);
    if (j.is_discarded()) return make_error(ErrorCode::Malformed, "signal timing: not valid JSON");
    Reader rd;
    const auto fail = [&]() { return make_error(ErrorCode::InvalidArgument, "signal timing: " + rd.err); };
    if (!rd.keys(j, "root", {"format", "amber_ms", "red_amber_ms", "clearance_ms", "green_base_ms", "green_per_lane_ms", "green_min_ms",
            "green_max_ms", "single_axis_red_ms", "max_cycle_ms", "axis_cross_max_permille", "driver", "sources"})) return fail();
    std::string format;
    if (!rd.text(j, "root", "format", format)) return fail();
    if (format != "g2m.signal_timing/1") return make_error(ErrorCode::Unsupported, "signal timing: format '" + format + "'");
    SignalTiming out;
    if (!rd.integer(j, "root", "amber_ms", 1000, 10000, out.amber_ms) ||
        !rd.integer(j, "root", "red_amber_ms", 0, 5000, out.red_amber_ms) ||
        !rd.integer(j, "root", "clearance_ms", 0, 20000, out.clearance_ms) ||
        !rd.integer(j, "root", "green_base_ms", 1000, 120000, out.green_base_ms) ||
        !rd.integer(j, "root", "green_per_lane_ms", 0, 60000, out.green_per_lane_ms) ||
        !rd.integer(j, "root", "green_min_ms", 1000, 120000, out.green_min_ms) ||
        !rd.integer(j, "root", "green_max_ms", 1000, 300000, out.green_max_ms) ||
        !rd.integer(j, "root", "single_axis_red_ms", 1000, 300000, out.single_axis_red_ms) ||
        !rd.integer(j, "root", "max_cycle_ms", 10000, 600000, out.max_cycle_ms) ||
        !rd.integer(j, "root", "axis_cross_max_permille", 1, 1000, out.axis_cross_max_permille)) return fail();
    if (out.green_min_ms > out.green_max_ms) { rd.fail("green_min_ms exceeds green_max_ms"); return fail(); }
    if (out.single_axis_red_ms < out.red_amber_ms + out.amber_ms + out.clearance_ms) {
        rd.fail("single_axis_red_ms is shorter than red_amber_ms + amber_ms + clearance_ms"); return fail();
    }
    const auto* driver = rd.field(j, "root", "driver");
    std::int32_t comfort = 0, maxd = 0, react = 0, lateral = 0, cosmin = 0;
    if (!driver || !rd.keys(*driver, "driver", {"comfortable_decel_mmps2", "max_decel_mmps2", "reaction_ms", "lateral_tolerance_mm", "heading_cos_min_permille"}) ||
        !rd.integer(*driver, "driver", "comfortable_decel_mmps2", 500, 10000, comfort) ||
        !rd.integer(*driver, "driver", "max_decel_mmps2", 500, 20000, maxd) ||
        !rd.integer(*driver, "driver", "reaction_ms", 0, 5000, react) ||
        !rd.integer(*driver, "driver", "lateral_tolerance_mm", 0, 20000, lateral) ||
        !rd.integer(*driver, "driver", "heading_cos_min_permille", 1, 1000, cosmin)) return fail();
    if (comfort > maxd) { rd.fail("driver.comfortable_decel_mmps2 exceeds max_decel_mmps2"); return fail(); }
    out.driver.comfortable_decel_mps2 = comfort / 1000.0;
    out.driver.max_decel_mps2 = maxd / 1000.0;
    out.driver.reaction_s = react / 1000.0;
    out.driver.lateral_tolerance_m = lateral / 1000.0;
    out.driver.heading_cos_min = cosmin / 1000.0;
    const auto* sources = rd.field(j, "root", "sources");
    if (!sources || !rd.object(*sources, "sources")) return fail();
    for (auto it = sources->begin(); it != sources->end(); ++it)
        if (!it.value().is_string()) { rd.fail("sources." + it.key() + " must be a string"); return fail(); }
    out.content_sha256 = Sha256::of(bytes);
    return out;
}

std::span<const std::byte> builtin_signal_timing_bytes() {
    return {reinterpret_cast<const std::byte*>(kSignalTiming), sizeof(kSignalTiming)};
}
const SignalTiming& builtin_signal_timing() {
    static const SignalTiming timing = [] {
        auto loaded = load_signal_timing(builtin_signal_timing_bytes());
        if (!loaded) {
            std::fprintf(stderr, "g2m: embedded data/signals/signal_timing.json is invalid: %s\n", loaded.error().message.c_str());
            std::abort();
        }
        return std::move(*loaded);
    }();
    return timing;
}

std::uint64_t SignalApproach::id() const {
    return Fnv1a64().i64(node_id).i64(way_id).u8(static_cast<std::uint8_t>(travel)).i64(mm_of(station_m)).value();
}

SignalState SignalPlan::state(std::uint32_t phase, double t_s) const {
    if (phase >= phases.size() || cycle_ms <= 0) return {SignalAspect::Red, 0.0};
    const std::int64_t t_ms = static_cast<std::int64_t>(std::floor(t_s * 1000.0));
    std::int64_t u = (t_ms + offset_ms) % cycle_ms;
    if (u < 0) u += cycle_ms;
    const SignalPhase& p = phases[phase];
    std::int64_t rel = u - p.start_ms;
    if (rel < 0) rel += cycle_ms;
    const std::int64_t ra = red_amber_ms, g = p.green_ms, a = amber_ms;
    SignalState s;
    std::int64_t left;
    if (rel < ra) { s.aspect = SignalAspect::RedAmber; left = ra - rel; }
    else if (rel < ra + g) { s.aspect = SignalAspect::Green; left = ra + g - rel; }
    else if (rel < ra + g + a) { s.aspect = SignalAspect::Amber; left = ra + g + a - rel; }
    else { s.aspect = SignalAspect::Red; left = cycle_ms - rel; }
    s.seconds_to_change = static_cast<double>(left) / 1000.0;
    return s;
}

namespace {
struct Accum {
    std::vector<const RoadFurniture*> lines;
    std::vector<SignalHead> heads;
    std::int64_t way_id = 0;
    std::uint32_t lanes = 0;
};
using Key = std::tuple<std::int64_t, std::size_t, std::uint8_t, std::int64_t>;   // node, entry, travel, station mm

// Unit vector of b - a; (0, 0) for a degenerate pair.
void unit(double ax, double ay, double bx, double by, double& ux, double& uy) {
    const double len = std::sqrt((bx - ax) * (bx - ax) + (by - ay) * (by - ay));
    if (len < 1e-9) { ux = uy = 0; return; }
    ux = (bx - ax) / len; uy = (by - ay) / len;
}
// A pseudo-angle of a direction folded to the half plane (monotone in the axis angle over [0, pi)), for the phase order.
double axis_rank(double dx, double dy) {
    if (dy < 0 || (dy == 0 && dx < 0)) { dx = -dx; dy = -dy; }
    return 1.0 - dx;
}
} // namespace

Result<std::vector<SignalPlan>> build_signal_plans(const RoadGeomTile& tile, const SignalTiming& timing, SignalPlanStats* stats) {
    std::map<Key, Accum> approaches;
    const auto key_of = [](const RoadFurniture& f) {
        return Key{f.node_id, f.entry_index, static_cast<std::uint8_t>(f.travel), mm_of(f.station_m)};
    };
    for (const auto& f : tile.furniture) {
        if (f.decline != FurnitureDecline::None || f.entry_index >= tile.entries.size()) continue;
        if (f.kind == FurnitureKind::Signal) {
            auto& a = approaches[key_of(f)];
            const auto post = signal_post(tile, f);
            if (!post) return make_error(post.error().code, "signal plan: " + post.error().message);
            SignalHead h; h.x = post->x; h.y = post->y; h.face_x = post->face_x; h.face_y = post->face_y;
            h.left = (f.flags & kFurnitureLeftPost) != 0;
            a.heads.push_back(h);
            a.way_id = tile.entries[f.entry_index].way_id;
        }
    }
    for (const auto& f : tile.furniture) {
        if (f.kind != FurnitureKind::StopLine || f.decline != FurnitureDecline::None || f.entry_index >= tile.entries.size()) continue;
        const auto it = approaches.find(key_of(f));
        if (it != approaches.end()) it->second.lines.push_back(&f);
    }

    std::map<std::int64_t, std::vector<SignalApproach>> by_node;
    for (auto& [key, a] : approaches) {
        if (a.lines.empty()) { if (stats) ++stats->unmatched_signals; continue; }
        const auto& entry = tile.entries[std::get<1>(key)];
        if (!entry.cross_section || !entry.profile) continue;
        const bool forward = static_cast<LaneDirection>(std::get<2>(key)) == LaneDirection::Forward;
        const RoadFurniture* lo = a.lines.front();
        const RoadFurniture* hi = a.lines.front();
        for (const auto* l : a.lines) {
            if (l->t_from < lo->t_from) lo = l;
            if (l->t_to > hi->t_to) hi = l;
        }
        const auto qlo = furniture_quad(tile, *lo), qhi = furniture_quad(tile, *hi);
        if (!qlo) return make_error(qlo.error().code, "signal plan: " + qlo.error().message);
        if (!qhi) return make_error(qhi.error().code, "signal plan: " + qhi.error().message);
        SignalApproach ap;
        ap.node_id = std::get<0>(key);
        ap.way_id = a.way_id;
        ap.travel = static_cast<LaneDirection>(std::get<2>(key));
        ap.station_m = lo->station_m;
        // quad = (s0,t_from), (s1,t_from), (s1,t_to), (s0,t_to): a is the middle of the t_from edge, b of the t_to edge.
        ap.ax = ((*qlo)[0].x + (*qlo)[1].x) / 2; ap.ay = ((*qlo)[0].y + (*qlo)[1].y) / 2;
        ap.bx = ((*qhi)[3].x + (*qhi)[2].x) / 2; ap.by = ((*qhi)[3].y + (*qhi)[2].y) / 2;
        ap.x = (ap.ax + ap.bx) / 2; ap.y = (ap.ay + ap.by) / 2;
        double ux = 0, uy = 0;
        unit((*qlo)[0].x, (*qlo)[0].y, (*qlo)[1].x, (*qlo)[1].y, ux, uy);   // along increasing station
        ap.dir_x = forward ? ux : -ux; ap.dir_y = forward ? uy : -uy;
        std::vector<std::pair<double, double>> groups;
        ap.lanes = static_cast<std::uint32_t>(furniture_lane_groups(*entry.cross_section, entry.profile->reference.length_m, ap.station_m,
            static_cast<LaneDirection>(std::get<2>(key)), groups));
        ap.heads = std::move(a.heads);
        std::sort(ap.heads.begin(), ap.heads.end(), [](const SignalHead& l, const SignalHead& r) {
            return std::tie(l.left, l.x, l.y) < std::tie(r.left, r.x, r.y); });
        by_node[ap.node_id].push_back(std::move(ap));
    }

    std::vector<SignalPlan> plans;
    for (auto& [node, list] : by_node) {
        std::sort(list.begin(), list.end(), [](const SignalApproach& l, const SignalApproach& r) { return l.id() < r.id(); });
        // Phase groups: approaches on one axis (opposed or parallel) share a phase; the representative is the group's first member.
        std::vector<std::vector<std::size_t>> groups;
        const double tol = timing.axis_cross_max_permille / 1000.0;
        for (std::size_t i = 0; i < list.size(); ++i) {
            bool placed = false;
            for (auto& g : groups) {
                const auto& rep = list[g.front()];
                if (std::abs(list[i].dir_x * rep.dir_y - list[i].dir_y * rep.dir_x) <= tol) { g.push_back(i); placed = true; break; }
            }
            if (!placed) groups.push_back({i});
        }
        std::stable_sort(groups.begin(), groups.end(), [&](const auto& l, const auto& r) {
            const double rl = axis_rank(list[l.front()].dir_x, list[l.front()].dir_y), rr = axis_rank(list[r.front()].dir_x, list[r.front()].dir_y);
            return rl != rr ? rl < rr : list[l.front()].id() < list[r.front()].id();
        });
        SignalPlan plan;
        plan.node_id = node;
        plan.amber_ms = timing.amber_ms; plan.red_amber_ms = timing.red_amber_ms; plan.clearance_ms = timing.clearance_ms;
        std::vector<std::int32_t> greens;
        for (std::size_t g = 0; g < groups.size(); ++g) {
            std::uint32_t lanes = 0;
            for (const auto i : groups[g]) { list[i].phase = static_cast<std::uint32_t>(g); lanes = std::max(lanes, list[i].lanes); }
            const std::int64_t green = static_cast<std::int64_t>(timing.green_base_ms) + static_cast<std::int64_t>(timing.green_per_lane_ms) * lanes;
            greens.push_back(static_cast<std::int32_t>(std::clamp<std::int64_t>(green, timing.green_min_ms, timing.green_max_ms)));
        }
        const std::int32_t fixed = timing.red_amber_ms + timing.amber_ms + timing.clearance_ms;
        const bool single = groups.size() == 1;
        std::int64_t cycle = 0;
        for (const auto g : greens) cycle += fixed + g;
        if (cycle > timing.max_cycle_ms) {
            std::int64_t sum_green = 0;
            for (const auto g : greens) sum_green += g;
            const std::int64_t available = std::max<std::int64_t>(0, timing.max_cycle_ms - static_cast<std::int64_t>(fixed) * static_cast<std::int64_t>(greens.size()));
            for (auto& g : greens) g = std::max<std::int32_t>(timing.green_min_ms, static_cast<std::int32_t>(static_cast<std::int64_t>(g) * available / sum_green));
            if (stats) ++stats->scaled_plans;
        }
        if (single) greens.push_back(timing.single_axis_red_ms - fixed);   // the virtual cross phase
        std::int32_t start = 0;
        for (const auto g : greens) { plan.phases.push_back({start, g}); start += fixed + g; }
        plan.cycle_ms = start;
        plan.offset_ms = static_cast<std::int32_t>(Fnv1a64().i64(node).value() % static_cast<std::uint64_t>(plan.cycle_ms));
        plan.approaches = std::move(list);
        if (stats) {
            ++stats->plans; stats->approaches += plan.approaches.size();
            for (const auto& a : plan.approaches) stats->heads += a.heads.size();
            if (single) ++stats->single_axis_plans;
        }
        plans.push_back(std::move(plan));
    }
    return plans;
}

SignalAdvice signal_advice(const SignalHit& hit, double speed_mps, const SignalDriverRules& rules) {
    if (hit.distance_m < 0) return SignalAdvice::Go;
    switch (hit.aspect) {
        case SignalAspect::Green: return SignalAdvice::Go;
        case SignalAspect::Amber: {
            const double v = std::max(0.0, speed_mps);
            const double stopping = v * rules.reaction_s + v * v / (2.0 * rules.comfortable_decel_mps2);
            return stopping <= hit.distance_m ? SignalAdvice::Stop : SignalAdvice::Go;
        }
        case SignalAspect::Red:
        case SignalAspect::RedAmber: return SignalAdvice::Stop;
    }
    return SignalAdvice::Stop;
}

double signal_stop_speed_cap(double distance_m, const SignalDriverRules& rules) {
    return distance_m <= 0 ? 0.0 : std::sqrt(2.0 * rules.comfortable_decel_mps2 * distance_m);
}

std::size_t SignalIndex::add(std::vector<SignalPlan> plans) {
    std::size_t added = 0;
    for (auto& plan : plans) {
        if (by_node_.contains(plan.node_id)) continue;
        const auto pi = static_cast<std::uint32_t>(plans_.size());
        by_node_.emplace(plan.node_id, pi);
        for (std::size_t a = 0; a < plan.approaches.size(); ++a) {
            const auto cx = static_cast<std::int32_t>(std::floor(plan.approaches[a].x / kCellM));
            const auto cy = static_cast<std::int32_t>(std::floor(plan.approaches[a].y / kCellM));
            grid_[cell_key(cx, cy)].push_back({pi, static_cast<std::uint32_t>(a)});
        }
        plans_.push_back(std::move(plan));
        ++added;
    }
    return added;
}

const SignalPlan* SignalIndex::plan_of_node(std::int64_t node_id) const {
    const auto it = by_node_.find(node_id);
    return it == by_node_.end() ? nullptr : &plans_[it->second];
}

void SignalIndex::collect(double x, double y, double radius_m, std::vector<Ref>& out) const {
    const auto c0x = static_cast<std::int32_t>(std::floor((x - radius_m) / kCellM)), c1x = static_cast<std::int32_t>(std::floor((x + radius_m) / kCellM));
    const auto c0y = static_cast<std::int32_t>(std::floor((y - radius_m) / kCellM)), c1y = static_cast<std::int32_t>(std::floor((y + radius_m) / kCellM));
    for (std::int32_t cx = c0x; cx <= c1x; ++cx)
        for (std::int32_t cy = c0y; cy <= c1y; ++cy) {
            const auto it = grid_.find(cell_key(cx, cy));
            if (it == grid_.end()) continue;
            for (const Ref& r : it->second) {
                const auto& a = plans_[r.plan].approaches[r.approach];
                if ((a.x - x) * (a.x - x) + (a.y - y) * (a.y - y) <= radius_m * radius_m) out.push_back(r);
            }
        }
    std::sort(out.begin(), out.end(), [&](const Ref& l, const Ref& r) {
        const auto& al = plans_[l.plan].approaches[l.approach]; const auto& ar = plans_[r.plan].approaches[r.approach];
        return std::make_tuple(al.id(), al.node_id) < std::make_tuple(ar.id(), ar.node_id);
    });
}

std::optional<SignalHit> SignalIndex::next_ahead(double x, double y, double hx, double hy, double horizon_m, double t_s,
    const SignalDriverRules& rules) const {
    std::vector<Ref> refs;
    collect(x, y, horizon_m + kBehindLineM + 1.0, refs);
    std::optional<SignalHit> best;
    for (const Ref& r : refs) {
        const SignalPlan& plan = plans_[r.plan];
        const SignalApproach& a = plan.approaches[r.approach];
        if (hx * a.dir_x + hy * a.dir_y < rules.heading_cos_min) continue;
        const double rx = x - a.x, ry = y - a.y;
        const double distance = -(rx * a.dir_x + ry * a.dir_y);
        if (distance < -kBehindLineM || distance > horizon_m) continue;
        const double lateral = rx * -a.dir_y + ry * a.dir_x;
        const double half = std::sqrt((a.bx - a.ax) * (a.bx - a.ax) + (a.by - a.ay) * (a.by - a.ay)) / 2;
        if (std::abs(lateral) > half + rules.lateral_tolerance_m) continue;
        if (best && best->distance_m <= distance) continue;   // collect() is ascending by id, so the first of equal distances wins
        SignalHit hit;
        hit.plan = &plan; hit.approach = &a; hit.distance_m = distance; hit.lateral_m = lateral;
        const SignalState s = plan.state_of(a, t_s);
        hit.aspect = s.aspect; hit.seconds_to_change = s.seconds_to_change;
        best = hit;
    }
    return best;
}
} // namespace g2m
